<?php

namespace App\Filament\Resources\Menus\Schemas;

use Filament\Forms\Components\Select;
use Filament\Forms\Components\TextInput;
use Filament\Forms\Components\Hidden;
use Filament\Forms\Components\Toggle;
use Filament\Schemas\Schema;

class MenuForm
{
    public static function configure(Schema $schema): Schema
    {
        return $schema
            ->components([
                // == ICON FIELD (HIDDEN) ==
                Hidden::make('icon')->default('heroicon-o-home'),

                // Field Logo
                \Filament\Forms\Components\FileUpload::make('logo')
                    ->label(__('Logo Menu'))
                    ->image()
                    ->imagePreviewHeight('150')
                    ->imageEditor()
                    ->imageEditorAspectRatios([
                        '1:1',
                    ])
                    ->imageResizeMode('contain')
                    ->imageResizeTargetWidth('512')
                    ->imageResizeTargetHeight('512')
                    ->disk('public')
                    ->directory('menus/logos')
                    ->visibility('public')
                    ->maxSize(1024) // 1MB max
                    ->acceptedFileTypes(['image/png', 'image/jpeg', 'image/jpg', 'image/svg+xml', 'image/webp'])
                    ->helperText(__('Upload logo persegi (1:1). Ukuran optimal: 512x512px. Max 1MB. Format: PNG (recommended), JPG, SVG, WebP.'))
                    ->downloadable()
                    ->openable()
                    ->columnSpanFull()
                    ->rules([
                        // Custom rules removed to support SVG better
                    ]),

                // Field Nama Menu
                TextInput::make('name')
                    ->label(__('Nama Menu'))
                    ->hiddenLabel()
                    ->required()
                    ->placeholder(__('Masukkan nama menu'))
                    ->maxLength(255),



                // Field Link
                TextInput::make('link')
                    ->label(__('Alamat Tautan'))
                    ->hiddenLabel()
                    ->placeholder(__('Atau ketik URL Manual (Contoh: /profil/visi-misi)'))
                    ->maxLength(255),

                // Hidden Parent ID
                Hidden::make('parent_id'),

                // Hidden Position
                Hidden::make('position')->default('portal'),

                // Field Urutan
                TextInput::make('order')
                    ->label(__('Urutan'))
                    ->hiddenLabel()
                    ->required()
                    ->numeric()
                    ->default(0),

                // Field Aktif (Toggle)
                Toggle::make('status')
                    ->label(__('Aktif'))
                    ->hiddenLabel()
                    ->onColor('info')
                    ->default(true)
                    ->inline(false),
            ]);
    }

